import json


_EVENT_FIELDS = {"seq", "id", "key", "op"}


def _reject_json_constant(constant):
    raise ValueError(f"Not a JSON value: {constant}")


def _valid_event(event):
    if not isinstance(event, dict):
        return False

    op = event.get("op")
    if op == "set":
        fields = _EVENT_FIELDS | {"value"}
    elif op == "delete":
        fields = _EVENT_FIELDS
    else:
        return False

    return (
        event.keys() == fields
        and type(event["seq"]) is int
        and event["seq"] >= 0
        and isinstance(event["id"], str)
        and bool(event["id"])
        and isinstance(event["key"], str)
        and bool(event["key"])
    )


def replay(lines, watermark):
    pending = []
    issues = []
    for number, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            event = json.loads(line, parse_constant=_reject_json_constant)
        except (ValueError, RecursionError):
            issues.append([number, "invalid"])
            continue
        if not _valid_event(event):
            issues.append([number, "invalid"])
        elif event["seq"] > watermark:
            pending.append((event["seq"], number, event))

    state = {}
    seen = set()
    # Line numbers break ties between events with the same sequence number.
    for seq, number, event in sorted(pending):
        event_id = event["id"]
        if event_id in seen:
            issues.append([number, "duplicate"])
            continue
        seen.add(event_id)
        if event["op"] == "set":
            state[event["key"]] = event["value"]
        else:
            state.pop(event["key"], None)
        watermark = seq

    return {"state": state, "issues": sorted(issues), "watermark": watermark}

